from common import *
import json, os
DM = drive("סיור 5 – השפלה – תל מרשה (סיכום הקורס)", "1FM9D6aRhifX9Emvl48uuMc9PjX54mkuL")
DG = drive("עלון גן לאומי בית גוברין–מרשה", "1ytSdvi6_tlIycXzvPT6T5OXzn22mR1ni")
