GEO = json.load(open(os.path.join(os.path.dirname(__file__), "..", "..", "public", "sites3d", "beitguvrin", "geo.json")))
AMPHI = next((s["osm"] for s in GEO["shapes"] if s["osm"].startswith("way/") and len(s["pts"]) > 4 and ("amphi" in (s["name"] + s["he"]).lower() or "אמפי" in s["he"])), None)
periods = [P(1, "מרשה המקראית", "Marésha biblique", "Biblical Maresha", "Библейская Мареша", "ימי בית ראשון", "époque du Premier Temple", "First Temple period", "эпоха Первого Храма"),
           P(2, "מרשה ההלניסטית", "Marésha hellénistique", "Hellenistic Maresha", "Эллинистическая Мареша", "538–40 לפנה״ס", "538–40 av. J.-C.", "538–40 BCE", "538–40 гг. до н. э."),
           P(3, "בית גוברין — אלאותרופוליס", "Beit Guvrin — Éleuthéropolis", "Beit Guvrin — Eleutheropolis", "Бейт-Гуврин — Элевтерополь", "המאות ה-1–7", "Ier–VIIe s.", "1st–7th c.", "I–VII вв."),
           P(4, "מערות הפעמון והצלבנים", "Grottes en cloche et croisés", "Bell caves and Crusaders", "Колоколообразные пещеры и крестоносцы", "המאות ה-7–12", "VIIe–XIIe s.", "7th–12th c.", "VII–XII вв."),
           P(5, "הגן הלאומי היום", "Le parc national aujourd’hui", "The national park today", "Национальный парк сегодня", "אתר מורשת עולמית", "patrimoine mondial", "World Heritage site", "объект всемирного наследия")]
M = []
M.append(dict(id="bg_tel", **{"from": 1, "to": 5}, certainty="attested", keep=True, pri=3, name=L("תל מרשה", "Tel Marésha", "Tel Maresha", "Тель Мареша"),
  text=L("אקרופוליס מימי בית ראשון — התל כ-24 דונם, העיר התחתית כ-350 דונם. רחבעם ביצר אותה; נפגעה במסע סנחריב (701) וננטשה ב-586. אחרי שיבת ציון ישבו בה אדומים וצידונים; יוחנן הורקנוס כבש וגייר את תושביה (111 לפנה״ס), והפרתים החריבו אותה (40 לפנה״ס).", "Acropole du Premier Temple — le tell fait environ 24 dounams, la ville basse environ 350. Roboam la fortifia ; touchée par Sennachérib (701), abandonnée en 586. Après le retour d’exil, Iduméens et Sidoniens s’y installèrent ; Jean Hyrcan la prit et convertit ses habitants (111 av. J.-C.) ; les Parthes la détruisirent (40 av. J.-C.).", "A First Temple acropolis — the mound about 24 dunams, the lower city about 350. Rehoboam fortified it; hit by Sennacherib (701) and abandoned in 586. After the return from exile Idumeans and Sidonians settled; John Hyrcanus took it and converted its people (111 BCE); the Parthians destroyed it (40 BCE).", "Акрополь эпохи Первого Храма — холм около 24 дунамов, нижний город около 350. Ровоам укрепил его; пострадал от Синаххериба (701), покинут в 586 г. После возвращения из плена здесь жили идумеи и сидоняне; Иоанн Гиркан взял город и обратил жителей (111 г. до н. э.); парфяне разрушили его (40 г. до н. э.)."),
  shape={"type": "marker", "at": "o:tel", "h": 9}, sources=[DM, DG, osm("node/278470166")]))
M.append(dict(id="bg_lowercity", **{"from": 2, "to": 5}, certainty="attested", name=L("העיר התחתית ומערותיה", "La ville basse et ses grottes", "The lower city and its caves", "Нижний город и его пещеры"),
  text=L("תכנון היפודמי — רחובות ישרים ורובעים. מתחת לכל בית מערה למשק הבית: קולומבריום (מאות גומחות — יונים? קבורה?), בית בד עם מפרכה בסגנון יווני ושני מתקני דחיסה, בורות מים בצורת פעמון. מערות הקבורה הצידוניות מעוטרות בציורים ובכתובות יווניות — אפולופנס, ראש קהילת הצידונים, וקרברוס בכניסה.", "Plan hippodamien — rues droites et îlots. Sous chaque maison, une grotte domestique : columbarium (des centaines de niches — pigeons ? sépulture ?), pressoir à huile à meule de type grec et deux presses, citernes en cloche. Les tombes sidoniennes sont peintes avec des inscriptions grecques — Apollophanès, chef des Sidoniens, et Cerbère à l’entrée.", "A Hippodamian plan — straight streets and blocks. Under every house a household cave: a columbarium (hundreds of niches — doves? burial?), an olive press with a Greek-style crusher and two presses, bell-shaped cisterns. The Sidonian tombs are painted with Greek inscriptions — Apollophanes, head of the Sidonians, and Cerberus at the entrance.", "Гипподамова планировка — прямые улицы и кварталы. Под каждым домом хозяйственная пещера: колумбарий (сотни ниш — голуби? погребения?), маслодавильня с жерновом греческого типа и двумя прессами, колоколообразные цистерны. Сидонские гробницы расписаны, с греческими надписями — Аполлофан, глава сидонян, и Цербер у входа."),
  debate=L("ייעוד הקולומבריום שנוי במחלוקת: גידול יונים (לקורבן, למאכל, לזבל) או קבורה משנית.", "La fonction du columbarium est discutée : élevage de pigeons (sacrifice, viande, engrais) ou sépulture secondaire.", "The columbarium’s use is debated: raising doves (sacrifice, meat, manure) or secondary burial.", "Назначение колумбария спорно: разведение голубей (жертвы, мясо, удобрение) или вторичное захоронение."),
  placementNote=L("המערות פזורות סביב התל; מיקומיהן אינם בנתוני המפה.", "Les grottes sont dispersées autour du tell ; leurs positions ne sont pas dans les données.", "The caves are scattered around the mound; their positions are not in the data.", "Пещеры разбросаны вокруг холма; их положения нет в данных."), sources=[DM, DG]))
M.append(dict(id="bg_bell", **{"from": 4, "to": 5}, certainty="attested", keep=True, pri=2, name=L("מערות הפעמון", "Les grottes en cloche", "The bell caves", "Колоколообразные пещеры"),
  text=L("מהתקופה הביזנטית עד הערבית: פורצים פתח קטן בשכבת הנארי הקשה וחוצבים את הקירטון הרך כלפי מטה, בהיקף הולך וגדל — לייצור סיד. כשמערות התחברו, התקרה קרסה. חלקן שימשו אחר כך ככנסיות.", "De l’époque byzantine à l’époque arabe : on perçait un petit trou dans la croûte de nari, puis on taillait la craie tendre vers le bas en s’élargissant — pour faire de la chaux. Quand des grottes se rejoignaient, le plafond s’effondrait. Certaines servirent ensuite d’églises.", "From the Byzantine to the Arab period: a small hole was cut through the hard nari crust, then the soft chalk was quarried downwards in a widening bell — to make lime. Where caves joined, the ceiling collapsed. Some later served as churches.", "От византийского до арабского периода: пробивали небольшое отверстие в твёрдой корке нари и вырубали мягкий мел вниз, расширяя «колокол», — для производства извести. Где пещеры сливались, свод обрушивался. Некоторые потом служили церквями."),
  shape={"type": "marker", "at": "o:bell", "h": 7}, sources=[DM, DG, osm("node/315766135")]))
M.append(dict(id="bg_church", **{"from": 3, "to": 5}, certainty="attested", keep=True, name=L("כנסיית סנט אנה (סנדחנה)", "L’église Sainte-Anne (Sandahanna)", "St Anne’s Church (Sandahanna)", "Церковь св. Анны (Сандаханна)"),
  text=L("כנסייה ביזנטית ששוקמה בידי הצלבנים; האפסיס עדיין עומד לגובה רב. השם הערבי סנדחנה (״סנטה אנה״) נשמר בשם התל — תל סנדחנה.", "Église byzantine restaurée par les croisés ; l’abside se dresse encore très haut. Le nom arabe Sandahanna (« Sainte Anne ») est resté au tell — Tell Sandahanna.", "A Byzantine church restored by the Crusaders; its apse still stands high. The Arabic name Sandahanna (“Santa Anna”) survives in the mound’s name — Tell Sandahanna.", "Византийская церковь, восстановленная крестоносцами; апсида всё ещё высоко стоит. Арабское название Сандаханна («Санта-Анна») сохранилось в имени холма — Телль-Сандаханна."),
  dims=L("56 × 52 מ׳ (לפי עלון הגן).", "56 × 52 m (d’après la brochure du parc).", "56 × 52 m (per the park leaflet).", "56 × 52 м (по буклету парка)."),
  shape={"type": "facade", "at": "o:church", "W": 16, "h": 14, "apse": True, "bearing": 90, "kind": "ashlar"}, sources=[DG, WG, osm("node/994342492")],
  placementNote=L("רק האפסיס מצויר, בנקודת המפה; כיוונו (מזרח) לפי מנהג הכנסיות.", "Seule l’abside est dessinée, au point cartographique ; tournée vers l’est comme les églises.", "Only the apse is drawn, at the map point; facing east as churches do.", "Нарисована только апсида, по точке на карте; обращена на восток, как в церквях.")))
M.append(dict(id="bg_villa", **{"from": 5, "to": 5}, certainty="attested", name=L("מבנה חפור על התל", "Bâtiment fouillé sur le tell", "Excavated building on the mound", "Раскопанное здание на холме"),
  text=L("מבנה חפור על מדרון התל, המסומן במפה ״The Villa״. תיארוכו ותפקידו אינם בסיכומי הקורס.", "Bâtiment fouillé sur la pente du tell, noté « The Villa » sur la carte. Sa date et sa fonction ne sont pas dans les résumés du cours.", "An excavated building on the mound’s slope, marked “The Villa” on the map. Its date and use are not in the course summaries.", "Раскопанное здание на склоне холма, отмечено на карте как «The Villa». Его дата и назначение в конспектах курса не указаны."),
  shape={"type": "footprint", "osm": "villa", "h": 3}, sources=[osm("way/732026188")]))
if AMPHI:
  M.append(dict(id="bg_amphi", **{"from": 3, "to": 5}, certainty="attested", keep=True, pri=3, name=L("האמפיתיאטרון הרומי", "L’amphithéâtre romain", "The Roman amphitheatre", "Римский амфитеатр"),
    text=L("אמפיתיאטרון רומי של העיר אלאותרופוליס (בית גוברין), כ-3,500 מקומות — למופעי לוחמים וחיות.", "Amphithéâtre romain de la ville d’Éleuthéropolis (Beit Guvrin), environ 3 500 places — pour les combats de gladiateurs et de bêtes.", "The Roman amphitheatre of Eleutheropolis (Beit Guvrin), about 3,500 seats — for gladiator and animal shows.", "Римский амфитеатр Элевтерополя (Бейт-Гуврина), около 3500 мест — для боёв гладиаторов и животных."),
    shape={"type": "amphi", "fit": "amphi"}, sources=[DG, WG, osm(AMPHI)]))
M.append(dict(id="bg_city", **{"from": 3, "to": 5}, certainty="attested", name=L("בית גוברין והצלבנים", "Beit Guvrin et les croisés", "Beit Guvrin and the Crusaders", "Бейт-Гуврин и крестоносцы"),
  text=L("אחרי חורבן מרשה עבר המרכז לבית גוברין, שזכתה למעמד עיר רומית (אלאותרופוליס). מרחץ רומי של יותר מ-4,000 מ״ר. ב-1136 הקימו הצלבנים מבצר בתוך העיר.", "Après la ruine de Marésha, le centre passa à Beit Guvrin, devenue cité romaine (Éleuthéropolis). Thermes romains de plus de 4 000 m². En 1136, les croisés y élevèrent une forteresse.", "After Maresha fell, the centre moved to Beit Guvrin, which became a Roman city (Eleutheropolis). A Roman bath of over 4,000 m². In 1136 the Crusaders built a fortress in the town.", "После гибели Мареши центр переместился в Бейт-Гуврин, ставший римским городом (Элевтерополь). Римские бани площадью более 4000 м². В 1136 г. крестоносцы построили здесь крепость."),
  placementNote=L("המרחץ והמבצר הצלבני אינם בנתוני המפה.", "Les thermes et la forteresse croisée ne sont pas dans les données.", "The bath and the Crusader fort are not in the map data.", "Бань и крепости крестоносцев нет в данных."), sources=[DG]))
write("beitguvrin", L("בית גוברין ומרשה", "Beit Guvrin et Marésha", "Beit Guvrin & Maresha", "Бейт-Гуврин и Мареша"), periods, M,
  dict({"tel": {"osm": "node/278470166"}, "bell": {"osm": "node/315766135"}, "church": {"osm": "node/994342492"}, "villa": {"osm": "way/732026188"}}, **({"amphi": {"osm": AMPHI}} if AMPHI else {})),
  {"at": {"off": "o:tel", "dx": 300, "dz": -150}, "dist": 560, "from": 170, "elev": 32}, 5, stone="limestone", tint="#efe3c8")
